def play_tic_tac_toe():
    # Initialize the board as a list of 9 empty strings
    board = [' '] * 9

    def print_board():
        print('Current board:')
        for i in range(0, 9, 3):
            print(' '.join(board[i:i+3]))

    def get_user_input():
        position = int(input("Enter the position to place your mark (1-9): ")) - 1
        return position

    def is_valid_position(position):
        return position >= 0 and position < 9

    def is_winner(board, mark):
        return (
            # Check rows
            (board[0] == mark and board[1] == mark and board[2] == mark) or
            (board[3] == mark and board[4] == mark and board[5] == mark) or
            (board[6] == mark and board[7] == mark and board[8] == mark) or

            # Check columns
            (board[0] == mark and board[3] == mark and board[6] == mark) or
            (board[1] == mark and board[4] == mark and board[7] == mark) or
            (board[2] == mark and board[5] == mark and board[8] == mark) or

            # Check diagonals
            (board[0] == mark and board[4] == mark and board[8] == mark) or
            (board[2] == mark and board[4] == mark and board[6] == mark)
        )

    def play_turn(board, mark):
        while True:
            position = get_user_input()
            if is_valid_position(position) and board[position] == ' ':
                board[position] = mark
                print_board()
                if is_winner(board, mark):
                    print(f"{mark} wins!")
                    return True
                else:
                    return False

    def play_game():
        current_player = 'X'
        while True:
            if play_turn(board, current_player):
                break
            else:
                current_player = 'O'

        if is_winner(board, ' '):
            print("It's a tie!")

    play_game()
```

This function creates a Tic-Tac-Toe board, allows the user to input a position to place their mark, checks for valid positions, determines the winner, and plays the game until a winner or a tie is achieved.
